            c1 = left.getOrDefault(a[i] / r, 0); 

        // Decrease the count in right hash 
        right.put(a[i],
        right.getOrDefault(a[i], 0) - 1); 

        // Number of right elements 
        c2 = right.getOrDefault(a[i] * r, 0); 

        // Calculate the answer 
        ans += c1 * c2; 

